from typing import List

def minDeletionSize(A: List[str]) -> int:
    n, m = len(A), len(A[0])
    dp = [1] * m

    for j in range(1, m):
        for i in range(j):
            if all(A[k][i] <= A[k][j] for k in range(n)):
                dp[j] = max(dp[j], dp[i] + 1)

    return m - max(dp)
